import{_ as o,c as a,o as r,ag as t}from"./chunks/framework.Dvzsf5EQ.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/glossary.md","filePath":"guide/glossary.md","lastUpdated":1764669597000}'),l={name:"guide/glossary.md"};function s(c,e,i,n,d,p){return r(),a("div",null,[...e[0]||(e[0]=[t('<h2 id="словник-термінів" tabindex="-1">Словник термінів <a class="header-anchor" href="#словник-термінів" aria-label="Permalink to &quot;Словник термінів&quot;">​</a></h2><p>У цьому розділі зібрані <strong>специфічні терміни</strong>, які часто зустрічаються в документації AgencyOS.</p><blockquote><p>Порада: при першій появі терміна в тексті документації можна робити посилання на відповідний розділ цього словника, наприклад:<br><code>див. [Композабли](/guide/glossary#композабли-composables)</code>.</p></blockquote><hr><h3 id="композабли-composables" tabindex="-1">Композабли (Composables) <a class="header-anchor" href="#композабли-composables" aria-label="Permalink to &quot;Композабли (Composables)&quot;">​</a></h3><p><strong>Що це:</strong><br> Функції <code>useSomething()</code>, які інкапсулюють повторювану логіку (стан, запити до API, роботу з браузером тощо) і можуть повторно використовуватись у різних компонентах.</p><p><strong>Де використовуються в проекті:</strong></p><ul><li>Директорія <code>composables/</code> (глобальні композабли, напр. <code>useScroll</code>)</li><li><code>modules/directus/runtime/composables/</code> (робота з Directus: <code>useDirectus</code>, <code>useDirectusAuth</code>, <code>useFiles</code>)</li><li><code>layers/portal/composables/</code>, <code>layers/proposals/composables/</code></li></ul><p><strong>Документація:</strong></p><ul><li>Vue Composables: <a href="https://vuejs.org/guide/reusability/composables.html" target="_blank" rel="noreferrer"><code>https://vuejs.org/guide/reusability/composables.html</code></a></li><li>VueUse: <a href="https://vueuse.org" target="_blank" rel="noreferrer"><code>https://vueuse.org</code></a></li><li>AgencyOS: <a href="/docs/modules/composables.html">Модулі / Composables</a></li></ul><hr><h3 id="nuxt-layer-layer-nuxt-layers" tabindex="-1">Nuxt Layer (Layer, Nuxt Layers) <a class="header-anchor" href="#nuxt-layer-layer-nuxt-layers" aria-label="Permalink to &quot;Nuxt Layer (Layer, Nuxt Layers)&quot;">​</a></h3><p><strong>Що це:</strong><br> Модульна надбудова Nuxt, яка дозволяє розбивати проект на “шари” з власними сторінками, компонентами, конфігурацією (<code>nuxt.config.ts</code>) і навіть модулями.</p><p><strong>Приклади в AgencyOS:</strong></p><ul><li><code>layers/portal/</code> — клієнтський портал</li><li><code>layers/proposals/</code> — система пропозицій (proposals)</li></ul><p><strong>Документація:</strong></p><ul><li>Nuxt Layers: <a href="https://nuxt.com/docs/guide/going-further/layers" target="_blank" rel="noreferrer"><code>https://nuxt.com/docs/guide/going-further/layers</code></a></li><li>AgencyOS: <a href="/docs/architecture/layers.html">Архітектура / Layers</a></li></ul><hr><h3 id="page-builder-pagebuilder" tabindex="-1">Page Builder (PageBuilder) <a class="header-anchor" href="#page-builder-pagebuilder" aria-label="Permalink to &quot;Page Builder (PageBuilder)&quot;">​</a></h3><p><strong>Що це:</strong><br> Компонент, який збирає сторінку з набору блоків (Hero, FAQ, Gallery тощо), збережених у Directus. Дозволяє редагувати структуру сторінок без змін у коді.</p><p><strong>Де дивитись:</strong></p><ul><li>Компонент: <code>components/PageBuilder.vue</code></li><li>Документація: <a href="/docs/components/page-builder.html">Компоненти / Page Builder</a></li></ul><hr><h3 id="блок-block-content-block" tabindex="-1">Блок (Block, Content Block) <a class="header-anchor" href="#блок-block-content-block" aria-label="Permalink to &quot;Блок (Block, Content Block)&quot;">​</a></h3><p><strong>Що це:</strong><br> Повторно використовувана секція сторінки (Hero, CTA, Testimonials, Steps…), яка зберігається як запис у Directus та рендериться через Page Builder.</p><p><strong>Приклади:</strong></p><ul><li><code>components/blocks/Hero.vue</code></li><li><code>components/blocks/Faqs.vue</code></li><li><code>components/blocks/Steps.vue</code></li></ul><p><strong>Документація:</strong></p><ul><li><a href="/docs/components/blocks.html">Компоненти / Blocks</a></li></ul><hr><h3 id="колекція-directus-collection" tabindex="-1">Колекція Directus (Collection) <a class="header-anchor" href="#колекція-directus-collection" aria-label="Permalink to &quot;Колекція Directus (Collection)&quot;">​</a></h3><p><strong>Що це:</strong><br> Таблиця в базі даних, керована Directus. Кожна колекція відповідає певному типу сутності: <code>pages</code>, <code>posts</code>, <code>os_projects</code>, <code>os_proposals</code> тощо.</p><p><strong>Де дивитись:</strong></p><ul><li>Directus Admin → Collections</li><li>AgencyOS: <a href="/docs/architecture/data-schema.html">Архітектура / Data Schema</a></li></ul><p>Офіційна документація Directus:<br><a href="https://docs.directus.io" target="_blank" rel="noreferrer"><code>https://docs.directus.io</code></a></p><hr><h3 id="singleton-directus-singleton" tabindex="-1">Singleton (Directus Singleton) <a class="header-anchor" href="#singleton-directus-singleton" aria-label="Permalink to &quot;Singleton (Directus Singleton)&quot;">​</a></h3><p><strong>Що це:</strong><br> Спеціальний тип колекції Directus, яка містить <strong>один запис</strong> (глобальні налаштування, SEO‑параметри тощо).</p><p><strong>Приклади в AgencyOS:</strong></p><ul><li><code>globals</code> — глобальні налаштування сайту</li></ul><p><strong>Документація:</strong></p><ul><li>Directus Singletons: <a href="https://docs.directus.io/app/data-model/singletons.html" target="_blank" rel="noreferrer"><code>https://docs.directus.io/app/data-model/singletons.html</code></a></li></ul><hr><h3 id="portal-клієнтськии-портал" tabindex="-1">Portal (Клієнтський портал) <a class="header-anchor" href="#portal-клієнтськии-портал" aria-label="Permalink to &quot;Portal (Клієнтський портал)&quot;">​</a></h3><p><strong>Що це:</strong><br> Автентифікований інтерфейс для клієнтів, де вони можуть переглядати проекти, задачі, файли, інвойси та виконувати оплати.</p><p><strong>Де дивитись:</strong></p><ul><li>Код: <code>layers/portal/</code></li><li>Документація: <a href="/docs/layers/portal.html">Layers / Portal</a> та <a href="/docs/modules/portal.html">Modules / Portal</a></li></ul><hr><h3 id="proposal-пропозиція" tabindex="-1">Proposal (Пропозиція) <a class="header-anchor" href="#proposal-пропозиція" aria-label="Permalink to &quot;Proposal (Пропозиція)&quot;">​</a></h3><p><strong>Що це:</strong><br> Комерційна пропозиція/оферта для клієнта з блоками контенту, цінами, секцією підпису (e‑signature).</p><p><strong>Де дивитись:</strong></p><ul><li>Код: <code>types/os/os-proposal.ts</code>, <code>layers/proposals/</code></li><li>Документація: <a href="/docs/layers/proposals.html">Layers / Proposals</a> та <a href="/docs/modules/proposals.html">Modules / Proposals</a></li></ul><hr><h3 id="seo-search-engine-optimization" tabindex="-1">SEO (Search Engine Optimization) <a class="header-anchor" href="#seo-search-engine-optimization" aria-label="Permalink to &quot;SEO (Search Engine Optimization)&quot;">​</a></h3><p><strong>Що це:</strong><br> Набір практик та налаштувань (meta‑теги, OG, sitemap, JSON‑LD, canonical), які покращують видимість сайту в пошукових системах.</p><p><strong>В AgencyOS:</strong></p><ul><li>Модуль <code>@nuxtjs/seo</code></li><li>Колекція <code>seo</code> в Directus</li><li>Автоматичне генерування OG‑зображень (<code>components/OgImage/Template.vue</code>)</li></ul><p><strong>Документація:</strong></p><ul><li>Nuxt SEO: <a href="https://nuxtseo.com" target="_blank" rel="noreferrer"><code>https://nuxtseo.com</code></a></li><li>AgencyOS: <a href="/docs/api/server-api.html">API / SEO та Server API</a></li></ul><hr><h3 id="og-image-open-graph-image" tabindex="-1">OG Image (Open Graph Image) <a class="header-anchor" href="#og-image-open-graph-image" aria-label="Permalink to &quot;OG Image (Open Graph Image)&quot;">​</a></h3><p><strong>Що це:</strong><br> Зображення, яке відображається при поширенні сторінки в соцмережах (Facebook, LinkedIn, X). Генерується динамічно на основі контенту сторінки.</p><p><strong>В AgencyOS:</strong></p><ul><li>Компонент: <code>components/OgImage/Template.vue</code></li><li>Конфігурація: <code>ogImage</code> в <code>nuxt.config.ts</code></li></ul><p>Документація Nuxt OG Image:<br><a href="https://nuxtseo.com/og-image" target="_blank" rel="noreferrer"><code>https://nuxtseo.com/og-image</code></a></p><hr><h3 id="crm-customer-relationship-management" tabindex="-1">CRM (Customer Relationship Management) <a class="header-anchor" href="#crm-customer-relationship-management" aria-label="Permalink to &quot;CRM (Customer Relationship Management)&quot;">​</a></h3><p><strong>Що це:</strong><br> Модуль для управління організаціями, контактами, угодами (deals), задачами та активностями.</p><p><strong>В AgencyOS:</strong></p><ul><li>Колекції <code>organizations</code>, <code>contacts</code>, <code>os_deals</code>, <code>os_tasks</code>, <code>os_activity</code></li><li>Інтерфейси в Directus + Portal</li></ul><p>Документація по структурі даних:</p><ul><li><a href="/docs/architecture/data-schema.html">Архітектура / Data Schema</a></li><li><a href="/docs/layers/portal.html">OS / Collections</a> (опис проектів, задач, інвойсів)</li></ul>',72)])])}const h=o(l,[["render",s]]);export{g as __pageData,h as default};
